// Phase fix: compute bend arc geometry from adjacent pipe route directions when source data
// does not carry explicit ARC_CENTER / BEND_PLANE_NORMAL / tangent attributes (e.g. CAESAR II).
function bendArcFrame(item, binding, nodesById, routesByToNode, routesByFromNode) {
  const evidence = item.bendEvidence || {};
  const startPoint = pointOrNull(evidence.startPosition) || pointOrNull(nodesById.get(String(evidence.fromNode || item?.placement?.fromNode))?.coord);
  const endPoint = pointOrNull(evidence.endPosition) || pointOrNull(nodesById.get(String(evidence.toNode || item?.placement?.toNode))?.coord);
  let center = pointOrNull(evidence.arcCenter);
  let normal = normalizedOrNull(evidence.normal);
  let startTangent = normalizedOrNull(evidence.startTangent);
  let endTangent = normalizedOrNull(evidence.endTangent);
  const majorRadiusMm = numberValue(evidence.bendRadiusMm);
  const bendAngleDeg = numberValue(evidence.bendAngleDeg);
  const tubeRadiusMm = numberValue(evidence.diameterMm) / 2;
  // Compute from adjacent route directions when explicit geometry is absent
  if (startPoint && endPoint && finitePositive(majorRadiusMm) && finitePositive(bendAngleDeg) && (!center || !normal || !startTangent || !endTangent)) {
    const fromNodeId = String(evidence.fromNode || item?.placement?.fromNode || '');
    const toNodeId = String(evidence.toNode || item?.placement?.toNode || '');
    const inRoute = routesByToNode?.get(fromNodeId)?.[0];
    const outRoute = routesByFromNode?.get(toNodeId)?.[0];
    const t0 = normalizedOrNull(inRoute?.direction);
    const t1 = normalizedOrNull(outRoute?.direction);
    if (t0 && t1) {
      const crossN = cross(t0, t1);
      const crossMag = magnitude(crossN);
      if (crossMag > VECTOR_EPSILON) {
        const computedNormal = crossN.map((v) => v / crossMag);
        const inwardDir = cross(computedNormal, t0);
        const inwardMag = magnitude(inwardDir);
        if (inwardMag > VECTOR_EPSILON) {
          const inward = inwardDir.map((v) => v / inwardMag);
